DROP TABLE IF EXISTS `payment_receipts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `payment_receipts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `booking_id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `payment_schedule_id` int(11) DEFAULT NULL,
  `installment_number` int(11) DEFAULT NULL,
  `amount_paid` decimal(10,2) NOT NULL DEFAULT 0.00,
  `payment_method` varchar(50) DEFAULT 'GCash',
  `gcash_reference_number` varchar(100) DEFAULT NULL,
  `transaction_reference` varchar(100) DEFAULT NULL,
  `payment_date` datetime DEFAULT NULL,
  `payment_status` varchar(30) DEFAULT 'PAID',
  `proof_filename` varchar(255) DEFAULT NULL,
  `receipt_number` varchar(60) DEFAULT NULL,
  `or_number` varchar(100) DEFAULT NULL,
  `receipt_path` varchar(255) DEFAULT NULL,
  `verified_by` int(11) DEFAULT NULL,
  `recorded_by` int(11) DEFAULT NULL,
  `recorded_by_name` varchar(100) DEFAULT NULL,
  `verified_at` datetime DEFAULT NULL,
  `rejection_reason` varchar(255) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_booking_id` (`booking_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_payment_date` (`payment_date`),
  KEY `idx_pr_schedule` (`payment_schedule_id`),
  KEY `idx_pr_gcash_ref` (`gcash_reference_number`),
  KEY `idx_pr_tx_ref` (`transaction_reference`),
  KEY `idx_pr_booking_id` (`booking_id`),
  KEY `idx_pr_sched_id` (`payment_schedule_id`)
) ENGINE=InnoDB AUTO_INCREMENT=150 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
